import tensorflow as tf
from tensorflow.keras import layers, models

def create_resnet_model(input_shape=(128, 128, 1), num_classes=234):
    def residual_block(x, filters, kernel_size=3, stride=1, activation='relu'):
        shortcut = x
        if stride != 1 or shortcut.shape[-1] != filters:
            shortcut = layers.Conv2D(filters, 1, strides=stride)(shortcut)
            shortcut = layers.BatchNormalization()(shortcut)

        x = layers.Conv2D(filters, kernel_size, strides=stride, padding='same')(x)
        x = layers.BatchNormalization()(x)
        x = layers.Activation(activation)(x)
        
        x = layers.Conv2D(filters, kernel_size, strides=1, padding='same')(x)
        x = layers.BatchNormalization()(x)

        x = layers.Add()([x, shortcut])
        x = layers.Activation(activation)(x)
        return x

    inputs = layers.Input(shape=input_shape)
    
    # Initial Convolutional Layer
    x = layers.Conv2D(16, 7, strides=2, padding='same')(inputs)
    x = layers.BatchNormalization()(x)
    x = layers.Activation('relu')(x)
    x = layers.MaxPooling2D(pool_size=(3, 3), strides=2, padding='same')(x)

    # Residual Blocks
    filters_list = [16, 32, 64]
    for filters in filters_list:
        x = residual_block(x, filters=filters)
        x = layers.MaxPooling2D(pool_size=(2, 2), strides=2, padding='same')(x)

    # Final Layers
    x = layers.GlobalAveragePooling2D()(x)
    x = layers.Dense(512, activation='relu')(x)
    outputs = layers.Dense(num_classes, activation='sigmoid')(x)  # Multi-label output

    model = models.Model(inputs=inputs, outputs=outputs)
    return model

